              $signed(Multiply_sub_temp[15:0])));
  assign Multiply_mul_temp_2 = FFT_M_out1_im * RomReal_out1;
  assign Multiply_add_cast = ((Multiply_mul_temp_2[41] == 1'b0) && (Multiply_mul_temp_2[40:33] != 8'b00000000) ? 16'sb0111111111111111 :
              ((Multiply_mul_temp_2[41] == 1'b1) && (Multiply_mul_temp_2[40:33] != 8'b11111111) ? 16'sb1000000000000000 :
              $signed(Multiply_mul_temp_2[33:18])));
  assign Multiply_add_cast_1 = {Multiply_add_cast[15], Multiply_add_cast};
  assign Multiply_mul_temp_3 = FFT_M_out1_re * RomImag_out1;
  assign Multiply_add_cast_2 = ((Multiply_mul_temp_3[41] == 1'b0) && (Multiply_mul_temp_3[40:33] != 8'b00000000) ? 16'sb0111111111111111 :
              ((Multiply_mul_temp_3[41] == 1'b1) && (Multiply_mul_temp_3[40:33] != 8'b11111111) ? 16'sb1000000000000000 :
              $signed(Multiply_mul_temp_3[33:18])));
  assign Multiply_add_cast_3 = {Multiply_add_cast_2[15], Multiply_add_cast_2};
  assign Multiply_add_temp = Multiply_add_cast_1 + Multiply_add_cast_3;
  assign Multiply_out1_im = ((Multiply_add_temp[16] == 1'b0) && (Multiply_add_temp[15] != 1'b0) ? 16'sb0111111111111111 :
              ((Multiply_add_temp[16] == 1'b1) && (Multiply_add_temp[15] != 1'b1) ? 16'sb1000000000000000 :
              $signed(Multiply_add_temp[15:0])));

  assign AccumZero_out1_re = 16'sb0000000000000000;
  assign AccumZero_out1_im = 16'sb0000000000000000;

  assign enb = clk_enable;

  always @(posedge clk or posedge reset)
    begin : AccumDelay_process
      if (reset == 1'b1) begin
        AccumDelay_bypass_delay_re <= 16'sb0000000000000000;
        AccumDelay_bypass_delay_im <= 16'sb0000000000000000;

        for(AccumDelay_t_1 = 32'sd0; AccumDelay_t_1 <= 32'sd127; AccumDelay_t_1 = AccumDelay_t_1 + 32'sd1) begin
          AccumDelay_reg_re[AccumDelay_t_1] <= 16'sb0000000000000000;
          AccumDelay_reg_im[AccumDelay_t_1] <= 16'sb0000000000000000;
        end

      end
      else begin
        if (enb && FFT_M_out2) begin
          AccumDelay_bypass_delay_re <= AccumDelay_bypass_delay_next_re;
          AccumDelay_bypass_delay_im <= AccumDelay_bypass_delay_next_im;

          for(AccumDelay_t_0_1 = 32'sd0; AccumDelay_t_0_1 <= 32'sd127; AccumDelay_t_0_1 = AccumDelay_t_0_1 + 32'sd1) begin
            AccumDelay_reg_re[AccumDelay_t_0_1] <= AccumDelay_reg_next_re[AccumDelay_t_0_1];
            AccumDelay_reg_im[AccumDelay_t_0_1] <= AccumDelay_reg_next_im[AccumDelay_t_0_1];
          end

        end
      end
    end

  always @* begin
    if (FFT_M_out2 == 1'b1) begin
      AccumDelay_out1_re = AccumDelay_reg_re[127];
      AccumDelay_out1_im = AccumDelay_reg_im[127];
    end
    else begin
      AccumDelay_out1_re = AccumDelay_bypass_delay_re;
      AccumDelay_out1_im = AccumDelay_bypass_delay_im;
    end
    AccumDelay_bypass_delay_next_re = AccumDelay_reg_re[127];
    AccumDelay_bypass_delay_next_im = AccumDelay_reg_im[127];
    AccumDelay_reg_next_re[0] = AccumSum_out1_re;
    AccumDelay_reg_next_im[0] = AccumSum_out1_im;

    for(AccumDelay_t_0_0 = 32'sd0; AccumDelay_t_0_0 <= 32'sd126; AccumDelay_t_0_0 = AccumDelay_t_0_0 + 32'sd1) begin
      AccumDelay_reg_next_re[AccumDelay_t_0_0 + 32'sd1] = AccumDelay_reg_re[AccumDelay_t_0_0];
      AccumDelay_reg_next_im[AccumDelay_t_0_0 + 32'sd1] = AccumDelay_reg_im[AccumDelay_t_0_0];
    end

  end

  assign FeedbackGate_out1_re = (feedbackGate == 1'b0 ? AccumZero_out1_re :
              AccumDelay_out1_re);
  assign FeedbackGate_out1_im = (feedbackGate == 1'b0 ? AccumZero_out1_im :
              AccumDelay_out1_im);

  assign AccumSum_add_cast = {{16{Multiply_out1_re[15]}}, Multiply_out1_re};
  assign AccumSum_add_cast_1 = {{16{FeedbackGate_out1_re[15]}}, FeedbackGate_out1_re};
  assign AccumSum_add_temp = AccumSum_add_cast + AccumSum_add_cast_1;
  assign AccumSum_out1_re = ((AccumSum_add_temp[31] == 1'b0) && (AccumSum_add_temp[30:15] != 16'b0000000000000000) ? 16'sb0111111111111111 :
              ((AccumSum_add_temp[31] == 1'b1) && (AccumSum_add_temp[30:15] != 16'b1111111111111111) ? 16'sb1000000000000000 :
              $signed(AccumSum_add_temp[15:0])));
  assign AccumSum_add_cast_2 = {{16{Multiply_out1_im[15]}}, Multiply_out1_im};
  assign AccumSum_add_cast_3 = {{16{FeedbackGate_out1_im[15]}}, FeedbackGate_out1_im};
  assign AccumSum_add_temp_1 = AccumSum_add_cast_2 + AccumSum_add_cast_3;
  assign AccumSum_out1_im = ((AccumSum_add_temp_1[31] == 1'b0) && (AccumSum_add_temp_1[30:15] != 16'b0000000000000000) ? 16'sb0111111111111111 :
              ((AccumSum_add_temp_1[31] == 1'b1) && (AccumSum_add_temp_1[30:15] != 16'b1111111111111111) ? 16'sb1000000000000000 :
              $signed(AccumSum_add_temp_1[15:0])));

  FFT_N u_FFT_N (.clk(clk),
                 .reset(reset),
                 .enb(clk_enable),
                 .dataIn_re(AccumSum_out1_re),  // sfix16_E1
                 .dataIn_im(AccumSum_out1_im),  // sfix16_E1
                 .validIn(partitionValid),
                 .syncReset(resetIn),
                 .dataOut_re(FFT_N_out1_re),  // sfix23_E1
                 .dataOut_im(FFT_N_out1_im),  // sfix23_E1
                 .validOut(FFT_N_out2)
                 );

  assign ScaleByM_cast = {{2{FFT_N_out1_re[22]}}, {FFT_N_out1_re, 21'b000000000000000000000}};
  assign ScaleByM_out1_re = ((ScaleByM_cast[45] == 1'b0) && (ScaleByM_cast[44:41] != 4'b0000) ? 16'sb0111111111111111 :
              ((ScaleByM_cast[45] == 1'b1) && (ScaleByM_cast[44:41] != 4'b1111) ? 16'sb1000000000000000 :
              $signed(ScaleByM_cast[41:26])));
  assign ScaleByM_cast_1 = {{2{FFT_N_out1_im[22]}}, {FFT_N_out1_im, 21'b000000000000000000000}};
  assign ScaleByM_out1_im = ((ScaleByM_cast_1[45] == 1'b0) && (ScaleByM_cast_1[44:41] != 4'b0000) ? 16'sb0111111111111111 :
              ((ScaleByM_cast_1[45] == 1'b1) && (ScaleByM_cast_1[44:41] != 4'b1111) ? 16'sb1000000000000000 :
              $signed(ScaleByM_cast_1[41:26])));

  assign MagnitudeSquared_real_square = ScaleByM_out1_re * ScaleByM_out1_re;

  assign MagnitudeSquared_imag_square = ScaleByM_out1_im * ScaleByM_out1_im;

  assign adder_add_cast = ((MagnitudeSquared_real_square[31] == 1'b0) && (MagnitudeSquared_real_square[30:29] != 2'b00) ? 16'b1111111111111111 :
              (MagnitudeSquared_real_square[31] == 1'b1 ? 16'b0000000000000000 :
              MagnitudeSquared_real_square[28:13]));
  assign adder_add_cast_1 = {1'b0, adder_add_cast};
  assign adder_add_cast_2 = ((MagnitudeSquared_imag_square[31] == 1'b0) && (MagnitudeSquared_imag_square[30:29] != 2'b00) ? 16'b1111111111111111 :
              (MagnitudeSquared_imag_square[31] == 1'b1 ? 16'b0000000000000000 :
              MagnitudeSquared_imag_square[28:13]));
  assign adder_add_cast_3 = {1'b0, adder_add_cast_2};
  assign adder_add_temp = adder_add_cast_1 + adder_add_cast_3;
  assign MagnitudeSquared_out1 = (adder_add_temp[16] != 1'b0 ? 16'b1111111111111111 :
              adder_add_temp[15:0]);

  OutputBinCounter u_OutputBinCounter (.clk(clk),
                                       .reset(reset),
                                       .enb(clk_enable),
                                       .magValid(FFT_N_out2),
                                       .resetIn(resetIn),
                                       .binIndex(binIndex_1),  // uint32
                                       .sumGate(sumGate)
                                       );

  PeakTracker u_PeakTracker (.clk(clk),
                             .reset(reset),
                             .enb(clk_enable),
                             .magSq(MagnitudeSquared_out1),  // ufix16_E5
                             .magValid(FFT_N_out2),
                             .binIndex(binIndex_1),  // uint32
                             .symbolIndex(symbolIndex_1),  // uint32
                             .peakValue(peakValue),  // ufix16_E5
                             .symbolValid(symbolValid_1)
                             );

  always @(posedge clk or posedge reset)
    begin : delayMatch_process
      if (reset == 1'b1) begin
        for(delayMatch_t_1 = 32'sd0; delayMatch_t_1 <= 32'sd33; delayMatch_t_1 = delayMatch_t_1 + 32'sd1) begin
          delayMatch_reg[delayMatch_t_1] <= 32'b00000000000000000000000000000000;
        end
      end
      else begin
        if (enb) begin
          for(delayMatch_t_0_1 = 32'sd0; delayMatch_t_0_1 <= 32'sd33; delayMatch_t_0_1 = delayMatch_t_0_1 + 32'sd1) begin
            delayMatch_reg[delayMatch_t_0_1] <= delayMatch_reg_next[delayMatch_t_0_1];
          end
        end
      end
    end

  always @* begin
    symbolIndex_2 = delayMatch_reg[33];
    delayMatch_reg_next[0] = symbolIndex_1;

    for(delayMatch_t_0_0 = 32'sd0; delayMatch_t_0_0 <= 32'sd32; delayMatch_t_0_0 = delayMatch_t_0_0 + 32'sd1) begin
      delayMatch_reg_next[delayMatch_t_0_0 + 32'sd1] = delayMatch_reg[delayMatch_t_0_0];
    end

  end

  always @(posedge clk or posedge reset)
    begin : delayMatch1_process
      if (reset == 1'b1) begin
        delayMatch1_reg <= {34{1'b0}};
      end
      else begin
        if (enb) begin
          delayMatch1_reg[0] <= symbolValid_1;
          delayMatch1_reg[32'sd33:32'sd1] <= delayMatch1_reg[32'sd32:32'sd0];
        end
      end
    end

  assign symbolValid = delayMatch1_reg[33];

  assign SpectrumZero_out1 = 16'b0000000000000000;

  always @(posedge clk or posedge reset)
    begin : SpectrumDelay_process
      if (reset == 1'b1) begin
        SpectrumDelay_bypass_delay <= 16'b0000000000000000;
        SpectrumDelay_reg <= 16'b0000000000000000;
      end
      else begin
        if (enb && FFT_N_out2) begin
          SpectrumDelay_bypass_delay <= SpectrumDelay_reg;
          SpectrumDelay_reg <= SpectrumSum_out1;
        end
      end
    end

  assign SpectrumDelay_out1 = (FFT_N_out2 == 1'b1 ? SpectrumDelay_reg :
              SpectrumDelay_bypass_delay);

  assign SpectrumGate_out1 = (sumGate == 1'b0 ? SpectrumZero_out1 :
              SpectrumDelay_out1);

  assign SpectrumSum_add_cast = {16'b0, MagnitudeSquared_out1};
  assign SpectrumSum_add_cast_1 = {14'b0, {SpectrumGate_out1, 2'b00}};
  assign SpectrumSum_add_temp = SpectrumSum_add_cast + SpectrumSum_add_cast_1;
  assign SpectrumSum_out1 = (SpectrumSum_add_temp[31:18] != 14'b00000000000000 ? 16'b1111111111111111 :
              SpectrumSum_add_temp[17:2]);

  assign GuardedSum_op_stage1 = {SpectrumSum_out1, 2'b00};

  assign GuardedSum_op_stage2 = {2'b0, peakValue};

  // ---- Tree max implementation ----
  assign GuardedSum_stage1_1_val = (GuardedSum_op_stage1 >= GuardedSum_op_stage2 ? GuardedSum_op_stage1 :
              GuardedSum_op_stage2);

  assign SumFloor_out1 = 16'b0000000000000001;

  assign GuardedSum_op_stage3 = {SumFloor_out1, 2'b00};

  assign GuardedSum_stage2_val = (GuardedSum_stage1_1_val >= GuardedSum_op_stage3 ? GuardedSum_stage1_1_val :
              GuardedSum_op_stage3);

  assign GuardedSum_out1 = GuardedSum_stage2_val[17:2];

  Confidence u_Confidence (.clk(clk),
                           .reset(reset),
                           .enb(clk_enable),
                           .dividend_in(peakValue),  // ufix16_E5
                           .divisor_in(GuardedSum_out1),  // ufix16_E7
                           .quotient(Confidence_out1)  // ufix16_En15
                           );

  assign confidence_1 = Confidence_out1;

  always @(posedge clk or posedge reset)
    begin : delayMatch2_process
      if (reset == 1'b1) begin
        for(delayMatch2_t_1 = 32'sd0; delayMatch2_t_1 <= 32'sd33; delayMatch2_t_1 = delayMatch2_t_1 + 32'sd1) begin
          delayMatch2_reg[delayMatch2_t_1] <= 16'b0000000000000000;
        end
      end
      else begin
        if (enb) begin
          for(delayMatch2_t_0_1 = 32'sd0; delayMatch2_t_0_1 <= 32'sd33; delayMatch2_t_0_1 = delayMatch2_t_0_1 + 32'sd1) begin
            delayMatch2_reg[delayMatch2_t_0_1] <= delayMatch2_reg_next[delayMatch2_t_0_1];
          end
        end
      end
    end

  always @* begin
    peakValue_1 = delayMatch2_reg[33];
    delayMatch2_reg_next[0] = peakValue;

    for(delayMatch2_t_0_0 = 32'sd0; delayMatch2_t_0_0 <= 32'sd32; delayMatch2_t_0_0 = delayMatch2_t_0_0 + 32'sd1) begin
      delayMatch2_reg_next[delayMatch2_t_0_0 + 32'sd1] = delayMatch2_reg[delayMatch2_t_0_0];
    end

  end

  assign peakMagnitudeSquared = peakValue_1;

  always @(posedge clk or posedge reset)
    begin : delayMatch3_process
      if (reset == 1'b1) begin
        for(delayMatch3_t_1 = 32'sd0; delayMatch3_t_1 <= 32'sd33; delayMatch3_t_1 = delayMatch3_t_1 + 32'sd1) begin
          delayMatch3_reg[delayMatch3_t_1] <= 16'b0000000000000000;
        end
      end
      else begin
        if (enb) begin
          for(delayMatch3_t_0_1 = 32'sd0; delayMatch3_t_0_1 <= 32'sd33; delayMatch3_t_0_1 = delayMatch3_t_0_1 + 32'sd1) begin
            delayMatch3_reg[delayMatch3_t_0_1] <= delayMatch3_reg_next[delayMatch3_t_0_1];
          end
        end
      end
    end

  always @* begin
    SpectrumSum_out1_1 = delayMatch3_reg[33];
    delayMatch3_reg_next[0] = SpectrumSum_out1;

    for(delayMatch3_t_0_0 = 32'sd0; delayMatch3_t_0_0 <= 32'sd32; delayMatch3_t_0_0 = delayMatch3_t_0_0 + 32'sd1) begin
      delayMatch3_reg_next[delayMatch3_t_0_0 + 32'sd1] = delayMatch3_reg[delayMatch3_t_0_0];
    end

  end

  assign spectrumSum = SpectrumSum_out1_1;

  always @(posedge clk or posedge reset)
    begin : delayMatch4_process
      if (reset == 1'b1) begin
        delayMatch4_reg <= {34{1'b0}};
      end
      else begin
        if (enb) begin
          delayMatch4_reg[0] <= symbolBoundary_1;
          delayMatch4_reg[32'sd33:32'sd1] <= delayMatch4_reg[32'sd32:32'sd0];
        end
      end
    end

  assign symbolBoundary = delayMatch4_reg[33];

  TimestampFifo u_TimestampFifo (.clk(clk),
                                 .reset(reset),
                                 .enb(clk_enable),
                                 .sampleCount(sampleCount),  // ufix64
                                 .symbolBoundary(symbolBoundary_1),
                                 .symbolValid(symbolValid_1),
                                 .resetIn(resetIn),
                                 .symbolSampleCount(symbolSampleCount_1),  // ufix64
                                 .timestampValid(timestampValid_1)
                                 );

  always @(posedge clk or posedge reset)
    begin : delayMatch5_process
      if (reset == 1'b1) begin
        for(delayMatch5_t_1 = 32'sd0; delayMatch5_t_1 <= 32'sd33; delayMatch5_t_1 = delayMatch5_t_1 + 32'sd1) begin
          delayMatch5_reg[delayMatch5_t_1] <= 64'h0000000000000000;
        end
      end
      else begin
        if (enb) begin
          for(delayMatch5_t_0_1 = 32'sd0; delayMatch5_t_0_1 <= 32'sd33; delayMatch5_t_0_1 = delayMatch5_t_0_1 + 32'sd1) begin
            delayMatch5_reg[delayMatch5_t_0_1] <= delayMatch5_reg_next[delayMatch5_t_0_1];
          end
        end
      end
    end

  always @* begin
    symbolSampleCount_2 = delayMatch5_reg[33];
    delayMatch5_reg_next[0] = symbolSampleCount_1;

    for(delayMatch5_t_0_0 = 32'sd0; delayMatch5_t_0_0 <= 32'sd32; delayMatch5_t_0_0 = delayMatch5_t_0_0 + 32'sd1) begin
      delayMatch5_reg_next[delayMatch5_t_0_0 + 32'sd1] = delayMatch5_reg[delayMatch5_t_0_0];
    end

  end

  always @(posedge clk or posedge reset)
    begin : delayMatch6_process
      if (reset == 1'b1) begin
        delayMatch6_reg <= {34{1'b0}};
      end
      else begin
        if (enb) begin
          delayMatch6_reg[0] <= timestampValid_1;
          delayMatch6_reg[32'sd33:32'sd1] <= delayMatch6_reg[32'sd32:32'sd0];
        end
      end
    end

  assign timestampValid = delayMatch6_reg[33];

  assign ce_out = clk_enable;

  assign symbolIndex = symbolIndex_2;

  assign symbolSampleCount = symbolSampleCount_2;

endmodule  // DUT

